tw.local.results = new tw.object.listOf.NameValuePair();

if( tw.local.records && tw.local.records.listLength > 0 ){
	for (var i=0; i<tw.local.records.listLength; i++) {
		tw.local.results[i] = new tw.object.NameValuePair();
		tw.local.results[i].name = tw.local.records[i]["VALUE"];
		tw.local.results[i].value = tw.local.records[i]["VALUE"];
	}
}

tw.local.staticVals = new tw.object.listOf.String();
